sys_script.script:
(function executeRule(current, previous) {

    function recalcEWT(ewtId) {
        if (!ewtId) return;
        var total = 0;
        var ga = new GlideAggregate('x_2316178_contin_0_time_card');
        ga.addQuery('employee_work_time', ewtId);
        ga.addQuery('report_type', 'work');
        ga.addAggregate('SUM', 'sunday');
        ga.addAggregate('SUM', 'monday');
        ga.addAggregate('SUM', 'tuesday');
        ga.addAggregate('SUM', 'wednesday');
        ga.addAggregate('SUM', 'thursday');
        ga.addAggregate('SUM', 'friday');
        ga.addAggregate('SUM', 'saturday');
        ga.query();
        if (ga.next()) {
            var days = ['sunday','monday','tuesday','wednesday','thursday','friday','saturday'];
            for (var i = 0; i < days.length; i++) {
                total += parseFloat(ga.getAggregate('SUM', days[i]) || 0);
            }
        }
        var ewt = new GlideRecord('x_2316178_contin_0_employee_work_time');
        if (ewt.get(ewtId)) {
            ewt.setValue('planned_hours', total);
            ewt.setWorkflow(false);
            ewt.autoSysFields(false);
            ewt.update();
        }
        return ewtId;
    }

    function recalcRP(rpId) {
        if (!rpId) return;
        var ph = 0, ah = 0;
        var ga = new GlideAggregate('x_2316178_contin_0_employee_work_time');
        ga.addQuery('resource_plan', rpId);
        ga.addAggregate('SUM', 'planned_hours');
        ga.addAggregate('SUM', 'actual_hours');
        ga.query();
        if (ga.next()) {
            ph = parseFloat(ga.getAggregate('SUM', 'planned_hours') || 0);
            ah = parseFloat(ga.getAggregate('SUM', 'actual_hours') || 0);
        }
        var rp = new GlideRecord('x_2316178_contin_0_resource_plan');
        if (rp.get(rpId)) {
            rp.setValue('planned_hours', ph);
            rp.setValue('actual_hours', ah);
            rp.setWorkflow(false);
            rp.autoSysFields(false);
            rp.update();
        }
    }

    // Current parent EWT
    var ewtId = current.getValue('employee_work_time');
    recalcEWT(ewtId);

    // Cascade to RP for current EWT
    if (ewtId) {
        var ewtGr = new GlideRecord('x_2316178_contin_0_employee_work_time');
        if (ewtGr.get(ewtId)) {
            recalcRP(ewtGr.getValue('resource_plan'));
        }
    }

    // If EWT reference changed (re-assignment), recalculate old parent chain
    var oldEwtId = (previous) ? previous.getValue('employee_work_time') : '';
    if (oldEwtId && oldEwtId != ewtId) {
        recalcEWT(oldEwtId);
        var oldEwt = new GlideRecord('x_2316178_contin_0_employee_work_time');
        if (oldEwt.get(oldEwtId)) {
            recalcRP(oldEwt.getValue('resource_plan'));
        }
    }

})(current, previous);
